125	func TestDiffResultSidesAndEvidence(t *testing.T) {
126		dir := t.TempDir()
127		artifact := sampleArtifact()
128		before := saveDiffReport(t, dir, artifact,
129			[]Rule{{ID: "r1", Kind: "static", Severity: "high", Invariant: "inv", Version: "1.0.0"}},
130			map[string]bool{"inv": false})
131		after := saveDiffReport(t, dir, artifact,
132			[]Rule{{ID: "r1", Kind: "static", Severity: "high", Invariant: "inv", Version: "1.0.0"}},
133			map[string]bool{"inv": true})
134	
135		diff, err := DiffStore(dir, before.ReportID, after.ReportID)
136		if err != nil {
137			t.Fatal(err)
138		}
139		if len(diff.Results) != 1 {
140			t.Fatalf("results = %d, want 1", len(diff.Results))
141		}
142		entry := diff.Results[0]
143		if entry.Change != ChangeResolvedDefect {
144			t.Fatalf("change = %q, want %q", entry.Change, ChangeResolvedDefect)
145		}
146		if entry.Before == nil || entry.After == nil {
147			t.Fatal("both sides must be present")
148		}
149		if entry.Before.Rule.Status != StatusDefect || entry.After.Rule.Status != StatusPass {
150			t.Errorf("statuses = %q/%q", entry.Before.Rule.Status, entry.After.Rule.Status)
151		}
152		if entry.Before.Finding == nil {
153			t.Fatal("defect side must carry evidence")
154		}
155		if entry.Before.Finding.ArtifactHash != ArtifactHash(artifact) {
156			t.Errorf("evidence artifact hash = %q", entry.Before.Finding.ArtifactHash)
157		}
158		if entry.Before.Finding.Version != "1.0.0" {
159			t.Errorf("evidence version = %q", entry.Before.Finding.Version)
160		}
161		if entry.After.Finding != nil {
162			t.Errorf("passing side must not carry evidence: %+v", entry.After.Finding)
163		}
164	}
