189	func TestDiffAllowsDifferentArtifactHashes(t *testing.T) {
190		dir := t.TempDir()
191		a1 := sampleArtifact()
192		a2 := sampleArtifact()
193		a2.Source = "VaultV2.sol"
194		rules := sampleRules()
195		before := saveDiffReport(t, dir, a1, rules, sampleInvariants())
196		after := saveDiffReport(t, dir, a2, rules, sampleInvariants())
197	
198		diff, err := DiffStore(dir, before.ReportID, after.ReportID)
199		if err != nil {
200			t.Fatal(err)
201		}
202		if !diff.ArtifactHashChanged {
203			t.Error("hash change must be reported")
204		}
205		if diff.ArtifactNameChanged {
206			t.Error("name did not change")
207		}
208		if diff.Before.Artifact.Hash != ArtifactHash(a1) || diff.After.Artifact.Hash != ArtifactHash(a2) {
209			t.Errorf("artifact refs = %+v / %+v", diff.Before.Artifact, diff.After.Artifact)
210		}
211		for _, r := range diff.Results {
212			if r.Change != ChangeNoChange {
213				t.Errorf("rule %s change = %q, want %q", r.RuleID, r.Change, ChangeNoChange)
214			}
215		}
216	}
