289	func TestDiffSameReportBothSides(t *testing.T) {
290		dir := t.TempDir()
291		report := saveDiffReport(t, dir, sampleArtifact(), sampleRules(), sampleInvariants())
292		diff, err := DiffStore(dir, report.ReportID, report.ReportID)
293		if err != nil {
294			t.Fatal(err)
295		}
296		if diff.ArtifactNameChanged || diff.ArtifactHashChanged {
297			t.Error("identical reports must not flag artifact changes")
298		}
