310	func TestDiffBothSidesEmpty(t *testing.T) {
311		dir := t.TempDir()
312		before := saveDiffReport(t, dir, sampleArtifact(), nil, nil)
313		after := saveDiffReport(t, dir, sampleArtifact(), nil, nil)
314		diff, err := DiffStore(dir, before.ReportID, after.ReportID)
315		if err != nil {
316			t.Fatal(err)
317		}
318		if len(diff.Results) != 0 {
319			t.Fatalf("results = %+v, want empty", diff.Results)
320		}
321		if diff.Summary != (DiffSummary{}) {
322			t.Errorf("summary = %+v, want all zero", diff.Summary)
323		}
324		// Empty results must render as [], not null.
325		out, err := json.Marshal(diff)
326		if err != nil {
327			t.Fatal(err)
328		}
329		if !strings.Contains(string(out), `"results":[]`) {
330			t.Errorf("empty results must serialize as []: %s", out)
331		}
332	}
