12	// auditBinary builds the CLI into a temp file once and returns its path. The
13	// tests exercise the real process boundary: exit status, stdout and stderr are
14	// observed exactly as an operator would see them.
15	func auditBinary(t *testing.T) string {
16		t.Helper()
17		bin := filepath.Join(t.TempDir(), "contractsentinel")
18		cmd := exec.Command("go", "build", "-o", bin, ".")
19		var out bytes.Buffer
20		cmd.Stdout = &out
21		cmd.Stderr = &out
