29	func writeInput(t *testing.T, dir, name, content string) string {
30		t.Helper()
31		path := filepath.Join(dir, name)
32		if err := os.WriteFile(path, []byte(content), 0o644); err != nil {
33			t.Fatal(err)
34		}
35		return path
36	}
37	
38	const nullInvariantInput = `{
39		"artifact": {"name":"Vault","abi":"abi","bytecode":"0x1","source":"Vault.sol"},
40		"rules": [{"id":"invariant-preserved","kind":"symbolic","severity":"critical","invariant":"balance-monotonic","version":"0.9.0"}],
41		"invariants": {"balance-monotonic": null}
42	}`
43	
44	const validInvariantInput = `{
45		"artifact": {"name":"Vault","abi":"abi","bytecode":"0x1","source":"Vault.sol"},
46		"rules": [{"id":"invariant-preserved","kind":"symbolic","severity":"critical","invariant":"balance-monotonic","version":"0.9.0"}],
47		"invariants": {"balance-monotonic": false}
48	}`
49	
50	// null 不变式：非零退出、原因进 stderr、stdout 不得出现成功报告。
51	func TestCLIAuditNullInvariantFailsCleanly(t *testing.T) {
52		bin := auditBinary(t)
53		work := t.TempDir()
54		input := writeInput(t, work, "in.json", nullInvariantInput)
55		store := filepath.Join(work, "reports")
56	
57		cmd := exec.Command(bin, "audit", "--input", input, "--store", store)
58		var stdout, stderr bytes.Buffer
59		cmd.Stdout = &stdout
60		cmd.Stderr = &stderr
61		err := cmd.Run()
62	
63		if err == nil {
64			t.Fatal("audit must exit non-zero for a null invariant value")
65		}
66		if exitErr, ok := err.(*exec.ExitError); ok && exitErr.ExitCode() == 0 {
67			t.Fatalf("exit code = 0, want non-zero")
68		}
69		if strings.Contains(stdout.String(), "reportId") || strings.Contains(stdout.String(), "发现缺陷") {
70			t.Fatalf("stdout must not contain a success report:\n%s", stdout.String())
71		}
72		if !strings.Contains(stderr.String(), "balance-monotonic") {
73			t.Fatalf("stderr must name the invariant:\n%s", stderr.String())
74		}
75		if !strings.Contains(stderr.String(), "boolean") {
76			t.Fatalf("stderr must say the value must be a boolean:\n%s", stderr.String())
77		}
78	}
79	
80	// 解析失败时不得创建尚不存在的报告目录或任何文件。
81	func TestCLIAuditNullInvariantCreatesNoStore(t *testing.T) {
82		bin := auditBinary(t)
83		work := t.TempDir()
84		input := writeInput(t, work, "in.json", nullInvariantInput)
85		store := filepath.Join(work, "nested", "reports")
86	
87		cmd := exec.Command(bin, "audit", "--input", input, "--store", store)
88		if out, err := cmd.CombinedOutput(); err == nil {
89			t.Fatalf("audit must fail, output:\n%s", out)
90		}
91		if _, err := os.Stat(store); !os.IsNotExist(err) {
92			t.Fatalf("failure must not create the report store: %v", err)
93		}
94	}
