126		}
127		after, err := listFiles(store)
128		if err != nil {
129			t.Fatal(err)
130		}
131		if len(after) != len(before) || after[0] != before[0] {
132			t.Fatalf("failure changed the store contents:\nbefore=%v\nafter=%v", before, after)
133		}
134		kept, err := os.ReadFile(existingPath)
135		if err != nil {
