326				{ID: "rule-b", Kind: "static", Severity: "low", Invariant: sharedInvariant, Version: "7"},
327			},
328			Checks: []cliWireCheck{
329				{ArtifactHash: hash, RuleID: "rule-a", Version: "7", Status: contractsentinel.StatusPass},
330				{ArtifactHash: hash, RuleID: "rule-b", Version: "7", Status: contractsentinel.StatusDefect, Note: note},
331			},
332		}
333		input := writeStructInput(t, work, "in.json", in)
334		store := filepath.Join(work, "reports")
335	
336		stdout, stderr, code := runCLIAudit(t, bin, input, store)
337		if code != 0 {
338			t.Fatalf("legal shared-invariant import must succeed, exit=%d stderr=%s", code, stderr)
339		}
340		report := decodeReport(t, stdout)
341	
342		statusByID := map[string]string{}
343		for _, r := range report.Rules {
344			statusByID[r.ID] = r.Status
345		}
346		if statusByID["rule-a"] != contractsentinel.StatusPass || statusByID["rule-b"] != contractsentinel.StatusDefect {
347			t.Fatalf("same invariant, different conclusions must be kept per rule: %+v", statusByID)
348		}
349		if len(report.Findings) != 1 {
350			t.Fatalf("exactly one rule defected, got findings %+v", report.Findings)
351		}
352		f := report.Findings[0]
353		if f.RuleID != "rule-b" {
354			t.Fatalf("defect must belong to rule-b only, got %q", f.RuleID)
355		}
356		if f.Version != "7" || f.Severity != "low" || f.Invariant != sharedInvariant || f.ArtifactHash != hash {
357			t.Fatalf("finding must carry rule-b's own binding, got %+v", f)
358		}
359		if f.Evidence != note {
360			t.Fatalf("evidence = %q, want the rule-b note %q", f.Evidence, note)
361		}
362		if f.Evidence == "invariant "+sharedInvariant+" does not hold" {
363			t.Fatal("evidence must not be replaced by a generic auto-generated note")
364		}
365	}
366	
367	// --- 任一记录产物哈希不匹配：整份拒绝，不产生任何部分报告或存储副作用 ---
368	
369	func TestCLIAuditImportChecksHashMismatchRejected(t *testing.T) {
370		bin := auditBinary(t)
371		work := t.TempDir()
372		hash := mixedArtifactHash(t)
373		in := mixedCheckInput(hash)
374		// 其余记录全部合法，仅工具缺失记录引用了另一份产物的哈希。
375		for i := range in.Checks {
376			if in.Checks[i].RuleID == "rule-tool" {
377				in.Checks[i].ArtifactHash = strings.Repeat("a", 64)
378			}
379		}
380		input := writeStructInput(t, work, "bad.json", in)
381		store := filepath.Join(work, "nested", "missing-store")
382	
383		stdout, stderr, code := runCLIAudit(t, bin, input, store)
384		if code == 0 {
385			t.Fatal("submission with a hash-mismatched check must exit non-zero")
386		}
387		if !strings.Contains(stderr, "rule-tool") {
388			t.Fatalf("stderr must name the involved rule:\n%s", stderr)
389		}
390		if !strings.Contains(stderr, "artifact hash mismatch") {
391			t.Fatalf("stderr must state the mismatch reason:\n%s", stderr)
392		}
393		assertNoPartialReport(t, stdout)
394		if _, err := os.Stat(store); !os.IsNotExist(err) {
395			t.Fatalf("rejected submission must not create the store directory: %v", err)
396		}
397	}
398	
399	// --- 任一记录规则版本不匹配：整份拒绝 ---
400	
401	func TestCLIAuditImportChecksVersionMismatchRejected(t *testing.T) {
402		bin := auditBinary(t)
403		work := t.TempDir()
404		hash := mixedArtifactHash(t)
405		in := mixedCheckInput(hash)
406		// 缺陷记录声称针对旧版本规则，与本次带版本规则不一致。
407		for i := range in.Checks {
408			if in.Checks[i].RuleID == "rule-defect" {
409				in.Checks[i].Version = "1.0.0"
410			}
411		}
412		input := writeStructInput(t, work, "bad.json", in)
413		store := filepath.Join(work, "nested", "missing-store")
414	
415		stdout, stderr, code := runCLIAudit(t, bin, input, store)
416		if code == 0 {
417			t.Fatal("submission with a version-mismatched check must exit non-zero")
418		}
419		if !strings.Contains(stderr, "rule-defect") {
420			t.Fatalf("stderr must name the involved rule:\n%s", stderr)
421		}
422		if !strings.Contains(stderr, "version mismatch") {
423			t.Fatalf("stderr must state the mismatch reason:\n%s", stderr)
424		}
425		assertNoPartialReport(t, stdout)
426		if _, err := os.Stat(store); !os.IsNotExist(err) {
427			t.Fatalf("rejected submission must not create the store directory: %v", err)
428		}
429	}
430	
431	// 拒绝是“提交无效”：stdout 不能把错误记录标成任何一种已知状态后部分输出。
432	func TestCLIAuditImportChecksMismatchHasNoStatusFragments(t *testing.T) {
433		bin := auditBinary(t)
434		work := t.TempDir()
435		hash := mixedArtifactHash(t)
436		in := mixedCheckInput(hash)
437		in.Checks[0].ArtifactHash = "0" + strings.TrimPrefix(hash, hash[:1])
438		input := writeStructInput(t, work, "bad.json", in)
439		store := filepath.Join(work, "reports")
440	
441		stdout, _, code := runCLIAudit(t, bin, input, store)
442		if code == 0 {
443			t.Fatal("mismatched submission must fail")
444		}
445		for _, marker := range []string{"reportId", "findings", contractsentinel.StatusDefect, contractsentinel.StatusTimeout,
446			contractsentinel.StatusToolMissing, contractsentinel.StatusUnchecked, contractsentinel.StatusPass} {
447			if strings.Contains(stdout, marker) {
448				t.Fatalf("stdout must not leak a partial report fragment %q:\n%s", marker, stdout)
449			}
